{
  "ok": true,
  "category": "comp",
  "operations": [
    {
      "name": "comp.create",
      "description": "Create a new composition.",
      "readOnly": false,
      "params": [
        {
          "name": "name",
          "type": "string",
          "required": true,
          "description": "Composition name"
        },
        {
          "name": "width",
          "type": "number",
          "required": true,
          "description": "Width in px"
        },
        {
          "name": "height",
          "type": "number",
          "required": true,
          "description": "Height in px"
        },
        {
          "name": "fps",
          "type": "number",
          "required": true,
          "description": "Frame rate"
        },
        {
          "name": "duration",
          "type": "number",
          "required": true,
          "description": "Duration in seconds"
        },
        {
          "name": "bgColor",
          "type": "array",
          "required": false,
          "description": "[r,g,b] 0-1"
        }
      ]
    },
    {
      "name": "comp.set_label",
      "description": "Set label color on comps. Can target by name, id, or pattern (e.g. 'review_id_*').",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name/id, or pattern with '*' wildcard"
        },
        {
          "name": "label",
          "type": "number",
          "required": true,
          "description": "Label index (0=None, 1=Red, 2=Yellow, 3=Aqua, 4=Pink, 5=Lavender, 6=Peach, 7=Sea Foam, 8=Blue, 9=Green, 10=Purple, 11=Orange, 12=Brown, 13=Fuchsia, 14=Cyan, 15=Sandstone, 16=Dark Green)"
        }
      ]
    },
    {
      "name": "comp.set_props",
      "description": "Set composition properties (bgColor, workAreaStart, workAreaDuration, shutterAngle, motionBlur, etc.).",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        },
        {
          "name": "props",
          "type": "object",
          "required": true,
          "description": "Object with keys to set"
        }
      ]
    },
    {
      "name": "comp.set_renderer",
      "description": "Switch a comp's 3D renderer: classic3d | advanced3d | cinema4d (or a raw matchName from comp.list_renderers). Advanced 3D is required for 3D model layers, parametric meshes, and environment lights to render.",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        },
        {
          "name": "renderer",
          "type": "string",
          "required": true,
          "description": "classic3d|advanced3d|cinema4d, or an exact renderer matchName"
        }
      ]
    },
    {
      "name": "comp.list_renderers",
      "description": "List the comp's available 3D renderer matchNames, the current one, and the friendly-name mapping used by comp.set_renderer.",
      "readOnly": true,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        }
      ]
    },
    {
      "name": "comp.set_work_area",
      "description": "Set the work area start and duration on a composition.",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        },
        {
          "name": "start",
          "type": "number",
          "required": true,
          "description": "Work area start in seconds"
        },
        {
          "name": "duration",
          "type": "number",
          "required": true,
          "description": "Work area duration in seconds"
        }
      ]
    },
    {
      "name": "comp.add_guide",
      "description": "Add a horizontal or vertical guide line to a comp (AE 16.1+).",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        },
        {
          "name": "orientation",
          "type": "string",
          "required": true,
          "description": "horizontal|vertical"
        },
        {
          "name": "position",
          "type": "number",
          "required": true,
          "description": "Position in px (y for horizontal, x for vertical)"
        }
      ]
    },
    {
      "name": "comp.remove_guide",
      "description": "Remove a guide from a comp by its 0-based index (see comp.list_guides).",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        },
        {
          "name": "guideIndex",
          "type": "number",
          "required": true,
          "description": "0-based guide index"
        }
      ]
    },
    {
      "name": "comp.set_guide",
      "description": "Move an existing guide to a new position (Item.setGuide). Orientation cannot be changed after creation — remove and re-add instead.",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        },
        {
          "name": "guideIndex",
          "type": "number",
          "required": true,
          "description": "0-based guide index"
        },
        {
          "name": "position",
          "type": "number",
          "required": true,
          "description": "New position in px (y for horizontal, x for vertical)"
        }
      ]
    },
    {
      "name": "comp.list_guides",
      "description": "List all guides on a comp with orientation and position (AE 16.1+).",
      "readOnly": true,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        }
      ]
    },
    {
      "name": "comp.delete",
      "description": "Delete a composition from the project.",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        }
      ]
    },
    {
      "name": "comp.precompose",
      "description": "Pre-compose selected layers into a new nested composition.",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Source comp name or id"
        },
        {
          "name": "layerIndices",
          "type": "array",
          "required": true,
          "description": "Array of 1-based layer indices to precompose"
        },
        {
          "name": "newName",
          "type": "string",
          "required": true,
          "description": "Name for the new comp"
        },
        {
          "name": "moveAll",
          "type": "boolean",
          "required": false,
          "description": "Move all attributes into new comp (default true)",
          "default": true
        }
      ]
    },
    {
      "name": "comp.duplicate",
      "description": "Duplicate a composition.",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id to duplicate"
        },
        {
          "name": "newName",
          "type": "string",
          "required": false,
          "description": "Name for the duplicate"
        }
      ]
    },
    {
      "name": "comp.info",
      "description": "Comp details + per-layer summaries (same payload as ae_comp_info). As a batch.run child, lets the same call verify what a preceding mutation did.",
      "readOnly": true,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        }
      ]
    }
  ]
}

{
  "ok": true,
  "category": "layer",
  "operations": [
    {
      "name": "layer.create_solid",
      "description": "Create a solid layer in a composition.",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        },
        {
          "name": "name",
          "type": "string",
          "required": false,
          "description": "Layer name",
          "default": "Solid"
        },
        {
          "name": "color",
          "type": "array",
          "required": false,
          "description": "[r,g,b] 0-1",
          "default": [
            1,
            1,
            1
          ]
        },
        {
          "name": "width",
          "type": "number",
          "required": false,
          "description": "Width in px (default: comp width)"
        },
        {
          "name": "height",
          "type": "number",
          "required": false,
          "description": "Height in px (default: comp height)"
        }
      ]
    },
    {
      "name": "layer.create_shape",
      "description": "Create an empty shape layer.",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        },
        {
          "name": "name",
          "type": "string",
          "required": false,
          "description": "Layer name"
        }
      ]
    },
    {
      "name": "layer.create_text",
      "description": "Create a text layer: point text by default, paragraph (box) text when boxSize is given, vertical when orientation='vertical' (AE 24.2+). Point<->box conversion is not scriptable, so pick the right kind here.",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        },
        {
          "name": "text",
          "type": "string",
          "required": false,
          "description": "Text content",
          "default": ""
        },
        {
          "name": "name",
          "type": "string",
          "required": false,
          "description": "Layer name"
        },
        {
          "name": "boxSize",
          "type": "array",
          "required": false,
          "description": "[width, height] — creates paragraph (box) text instead of point text"
        },
        {
          "name": "boxPosition",
          "type": "array",
          "required": false,
          "description": "[x, y] top-left of the box in layer space (box text only)"
        },
        {
          "name": "orientation",
          "type": "string",
          "required": false,
          "description": "horizontal|vertical (vertical needs AE 24.2+)",
          "default": "horizontal"
        }
      ]
    },
    {
      "name": "layer.create_null",
      "description": "Create a null object layer.",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        },
        {
          "name": "name",
          "type": "string",
          "required": false,
          "description": "Layer name"
        }
      ]
    },
    {
      "name": "layer.create_camera",
      "description": "Create a camera layer.",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        },
        {
          "name": "name",
          "type": "string",
          "required": false,
          "description": "Layer name",
          "default": "Camera"
        }
      ]
    },
    {
      "name": "layer.create_light",
      "description": "Create a light layer.",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        },
        {
          "name": "name",
          "type": "string",
          "required": false,
          "description": "Layer name",
          "default": "Light"
        },
        {
          "name": "lightType",
          "type": "string",
          "required": false,
          "description": "spot|parallel|point|ambient|environment (environment needs AE 24.3+ / Advanced 3D)",
          "default": "spot"
        }
      ]
    },
    {
      "name": "layer.create_parametric_mesh",
      "description": "Create a parametric 3D mesh layer (LayerCollection.addParametricMesh, AE 26.3+): cube|sphere|plane|cylinder|cone|torus. Best rendered with the Advanced 3D renderer (comp.set_renderer).",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        },
        {
          "name": "name",
          "type": "string",
          "required": false,
          "description": "Layer name",
          "default": "Mesh"
        },
        {
          "name": "meshType",
          "type": "string",
          "required": true,
          "description": "cube|sphere|plane|cylinder|cone|torus"
        }
      ]
    },
    {
      "name": "layer.delete",
      "description": "Delete layers. comp supports pattern ('review_id_*'). layer supports index, name, 'selected', 'all'.",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name/id/pattern (e.g. 'review_id_*')"
        },
        {
          "name": "layer",
          "type": "any",
          "required": true,
          "description": "Layer index, name, 'selected', or 'all'"
        }
      ]
    },
    {
      "name": "layer.duplicate",
      "description": "Duplicate a layer. Returns the new layer's index.",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        },
        {
          "name": "layer",
          "type": "any",
          "required": true,
          "description": "1-based layer index, or the layer name"
        },
        {
          "name": "newName",
          "type": "string",
          "required": false,
          "description": "Name for the duplicate"
        }
      ]
    },
    {
      "name": "layer.set_parent",
      "description": "Set or clear a layer's parent. By default AE compensates the child's transform so it doesn't move; jump=true skips compensation (setParentWithJump) so the child adopts the parent's space.",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        },
        {
          "name": "layer",
          "type": "any",
          "required": true,
          "description": "1-based child layer index, or the layer name"
        },
        {
          "name": "parentLayer",
          "type": "any",
          "required": true,
          "description": "1-based parent layer index or name. Pass null or 0 to unparent.",
          "nullable": true
        },
        {
          "name": "jump",
          "type": "boolean",
          "required": false,
          "description": "true = no transform compensation (setParentWithJump). Default false.",
          "default": false
        }
      ]
    },
    {
      "name": "layer.scene_edit_detection",
      "description": "Run Scene Edit Detection on a video layer (Layer.doSceneEditDetection, AE 22.3+): find cuts in edited footage and mark or split at them.",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        },
        {
          "name": "layer",
          "type": "any",
          "required": true,
          "description": "1-based layer index, or the layer name"
        },
        {
          "name": "mode",
          "type": "string",
          "required": true,
          "description": "markers (add layer markers) | split (split layer) | splitPrecomp (split + precompose each) | none (detect only)"
        }
      ]
    },
    {
      "name": "layer.move",
      "description": "Move a layer to a new stacking position (1 = top).",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        },
        {
          "name": "layer",
          "type": "any",
          "required": true,
          "description": "1-based current layer index, or the layer name"
        },
        {
          "name": "toIndex",
          "type": "number",
          "required": true,
          "description": "1-based target index, within 1..numLayers"
        }
      ]
    },
    {
      "name": "layer.create_footage",
      "description": "Add an existing project item (footage or comp) as a layer in a composition.",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        },
        {
          "name": "sourceItemId",
          "type": "number",
          "required": true,
          "description": "Project item id to use as source"
        },
        {
          "name": "name",
          "type": "string",
          "required": false,
          "description": "Layer name"
        }
      ]
    },
    {
      "name": "layer.set_enabled",
      "description": "Enable or disable a layer by name or index. Can target all comps matching a pattern.",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name/id, or '*' for all comps, or 'review_id_*' for pattern match"
        },
        {
          "name": "layer",
          "type": "any",
          "required": true,
          "description": "Layer index (number) or name (string)"
        },
        {
          "name": "enabled",
          "type": "boolean",
          "required": true,
          "description": "true=visible, false=hidden"
        }
      ]
    },
    {
      "name": "layer.set_guide",
      "description": "Set guideLayer on/off for a layer. Can target all comps matching a pattern.",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name/id, or '*' for all comps, or 'review_id_*' for pattern match"
        },
        {
          "name": "layer",
          "type": "any",
          "required": true,
          "description": "Layer index (number) or name (string)"
        },
        {
          "name": "guide",
          "type": "boolean",
          "required": true,
          "description": "true=guide layer, false=normal"
        }
      ]
    },
    {
      "name": "layer.set_props",
      "description": "Set basic layer properties. layer can be index, name, 'selected', or 'all'. Enum-valued attributes accept string names: quality (best|draft|wireframe), samplingQuality (bilinear|bicubic), frameBlendingType (off|frameMix|pixelMotion), autoOrient (off|alongPath|cameraOrPointOfInterest|charactersTowardCamera), blendingMode, lightType (spot|parallel|point|ambient|environment).",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        },
        {
          "name": "layer",
          "type": "any",
          "required": true,
          "description": "Layer index, name, 'selected', or 'all'"
        },
        {
          "name": "props",
          "type": "object",
          "required": true,
          "description": "Object with keys to set, e.g. { name: 'foo', enabled: false, label: 5, threeDLayer: true }"
        }
      ]
    },
    {
      "name": "layer.add_guide",
      "description": "Add a ruler guide to a layer's Layer panel view (Layer.addGuide, AE 16.1+). Comp-panel guides live under comp.add_guide.",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        },
        {
          "name": "layer",
          "type": "any",
          "required": true,
          "description": "1-based layer index, or the layer name"
        },
        {
          "name": "orientation",
          "type": "string",
          "required": true,
          "description": "horizontal|vertical"
        },
        {
          "name": "position",
          "type": "number",
          "required": true,
          "description": "Position in px (y for horizontal, x for vertical)"
        }
      ]
    },
    {
      "name": "layer.remove_guide",
      "description": "Remove a Layer-panel ruler guide by its 0-based index (see layer.list_guides).",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        },
        {
          "name": "layer",
          "type": "any",
          "required": true,
          "description": "1-based layer index, or the layer name"
        },
        {
          "name": "guideIndex",
          "type": "number",
          "required": true,
          "description": "0-based guide index"
        }
      ]
    },
    {
      "name": "layer.move_guide",
      "description": "Move an existing Layer-panel ruler guide to a new position (Layer.setGuide). Named move_guide because layer.set_guide already means the guide-LAYER flag.",
      "readOnly": false,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        },
        {
          "name": "layer",
          "type": "any",
          "required": true,
          "description": "1-based layer index, or the layer name"
        },
        {
          "name": "guideIndex",
          "type": "number",
          "required": true,
          "description": "0-based guide index"
        },
        {
          "name": "position",
          "type": "number",
          "required": true,
          "description": "New position in px"
        }
      ]
    },
    {
      "name": "layer.list_guides",
      "description": "List a layer's Layer-panel ruler guides with orientation and position (AE 16.1+).",
      "readOnly": true,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        },
        {
          "name": "layer",
          "type": "any",
          "required": true,
          "description": "1-based layer index, or the layer name"
        }
      ]
    },
    {
      "name": "layer.bounds",
      "description": "Measure a layer's rendered bounds via sourceRectAtTime — essential for aligning/fitting text and shape layers. Returns layer-space rect and, when the host supports it, comp-space corners.",
      "readOnly": true,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        },
        {
          "name": "layer",
          "type": "any",
          "required": true,
          "description": "1-based layer index, or the layer name"
        },
        {
          "name": "time",
          "type": "number",
          "required": false,
          "description": "Time in seconds (default: current comp time)"
        },
        {
          "name": "includeExtents",
          "type": "boolean",
          "required": false,
          "description": "Include pixel extents beyond the layer edges (default false)",
          "default": false
        }
      ]
    },
    {
      "name": "layer.convert_point",
      "description": "Convert a point between layer source space and comp space (sourcePointToComp / compPointToSource, AE 13.2+; designed for text layers — evaluates at the first character at the given time).",
      "readOnly": true,
      "params": [
        {
          "name": "comp",
          "type": "any",
          "required": true,
          "description": "Comp name or id"
        },
        {
          "name": "layer",
          "type": "any",
          "required": true,
          "description": "1-based layer index, or the layer name"
        },
        {
          "name": "direction",
          "type": "string",
          "required": true,
          "description": "sourceToComp|compToSource"
        },
        {
          "name": "point",
          "type": "array",
          "required": true,
          "description": "[x, y] point to convert"
        },
        {
          "name": "time",
          "type": "number",
          "required": false,
          "description": "Evaluate at this time (default: current comp time)"
        }
      ]
    },
